class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int minLen = Integer.MAX_VALUE;
        int sum = 0;
        int left = 0;

        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];

            // Shrink window while sum is valid
            while (sum >= target) {
                minLen = Math.min(minLen, right - left + 1);
                sum -= nums[left];
                left++;
            }
        }

        return minLen == Integer.MAX_VALUE ? 0 : minLen;
    }
}

class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int n = nums.length;
        long[] prefix = new long[n + 1];

        // Build prefix sum
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int minLen = Integer.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            // Find smallest j where prefix[j] - prefix[i] >= target
            // => prefix[j] >= prefix[i] + target
            long toFind = prefix[i] + target;
            int j = lowerBound(prefix, i + 1, n + 1, toFind);

            if (j <= n) {
                minLen = Math.min(minLen, j - i);
            }
        }

        return minLen == Integer.MAX_VALUE ? 0 : minLen;
    }

    private int lowerBound(long[] arr, int start, int end, long target) {
        while (start < end) {
            int mid = start + (end - start) / 2;
            if (arr[mid] >= target) {
                end = mid;
            } else {
                start = mid + 1;
            }
        }
        return start;
    }
}
